+    fn unrelated_mmio_does_not_wait_for_the_platform_timer_lock() {
+        if !std::path::Path::new("/dev/kvm").exists() {
+            eprintln!("SKIP MMIO clock synchronization: /dev/kvm absent");
+            return;
+        }
+        let (shared, chipset) = mmio_clock_vm();
