+            let access = shared.clone();
+            let thread = std::thread::spawn(move || {
+                if write {
+                    access.mmio_write(crate::layout::MMIO32_BASE, &[0]);
+                } else {
+                    let mut byte = [0];
+                    access.mmio_read(crate::layout::MMIO32_BASE, &mut byte);
+                    assert_eq!(byte, [0xff]);
+                }
+                sent.send(()).unwrap();
+            });
+            let completed = received.recv_timeout(Duration::from_millis(250)).is_ok();
+            drop(timer);
+            thread.join().unwrap();
+            assert!(completed, "unrelated MMIO waited for the RTC lock");
+        }
+    }
