+    #[test]
+    fn mmio_clock_keeps_hpet_current_and_frozen_when_paused() {
+        if !std::path::Path::new("/dev/kvm").exists() {
+            eprintln!("SKIP HPET MMIO clock: /dev/kvm absent");
+            return;
+        }
+        let (shared, _) = mmio_clock_vm();
+        shared.mmio_write(0xfed00010, &1u64.to_le_bytes());
+        std::thread::sleep(Duration::from_millis(2));
+        let mut counter = [0; 8];
+        shared.mmio_read(0xfed000f0, &mut counter);
+        assert!(u64::from_le_bytes(counter) > 0);
+        shared.clock_running(false);
+        shared.mmio_read(0xfed000f0, &mut counter);
+        let paused = counter;
+        std::thread::sleep(Duration::from_millis(2));
+        shared.mmio_write(0xfed00108, &100u64.to_le_bytes());
+        shared.mmio_read(0xfed000f0, &mut counter);
+        assert_eq!(counter, paused);
+        shared.clock_running(true);
+        std::thread::sleep(Duration::from_millis(2));
+        shared.mmio_read(0xfed000f0, &mut counter);
+        assert!(u64::from_le_bytes(counter) > u64::from_le_bytes(paused));
+    }
